// MetricsRepository abstracts a metrics storage backend so that different
// implementations (in-memory, file-backed, database-backed) can be selected
// in main.go via configuration without touching existing storage code.
type MetricsRepository interface {
	AddGauge(name string, value float64)
	AddCounter(name string, value int64)
	CheckGaugeType(name string) bool
	CheckCounterType(name string) bool
	GetTypeValue(name string) any
	AddBatch(data models.MetricsList) error
}

var _ MetricsRepository = (*MemStorage)(nil)
